// Minimal GraphQL document validator, used by tests to catch malformed queries
// generated by the browse builder (unbalanced braces, undeclared variables,
// variables used but never declared, duplicate arguments, empty selection sets).
//
// This is deliberately small: it validates the shapes our own code generates,
// not arbitrary GraphQL.

const NAME_RE = /[_A-Za-z][_0-9A-Za-z]*/y

function tokenize(source) {
  const tokens = []
  let i = 0
  while (i < source.length) {
    const ch = source[i]
    if (ch === '#') {
      while (i < source.length && source[i] !== '\n') i += 1
      continue
    }
    if (/\s|,/.test(ch)) {
      i += 1
      continue
    }
    if ('{}()[]:!=$@'.includes(ch)) {
      tokens.push({ type: ch, value: ch, pos: i })
      i += 1
      continue
    }
    if (ch === '"' || ch === '`') {
      const quote = ch
      const triple = source.startsWith(quote.repeat(3), i)
      let j = i + (triple ? 3 : 1)
      while (j < source.length) {
        if (source[j] === '\\') {
          j += 2
          continue
        }
        if (triple ? source.startsWith(quote.repeat(3), j) : source[j] === quote) {
          j += triple ? 3 : 1
          break
        }
        j += 1
      }
      tokens.push({ type: 'string', value: source.slice(i, j), pos: i })
      i = j
      continue
    }
    if (/[-0-9]/.test(ch)) {
      let j = i
      while (j < source.length && /[-+.0-9eE]/.test(source[j])) j += 1
      tokens.push({ type: 'number', value: source.slice(i, j), pos: i })
      i = j
      continue
    }
    NAME_RE.lastIndex = i
    const m = NAME_RE.exec(source)
    if (m) {
      tokens.push({ type: 'name', value: m[0], pos: i })
      i += m[0].length
      continue
    }
    throw new Error(`Unexpected character "${ch}" at ${i}`)
  }
  return tokens
}

/**
 * @param {string} source GraphQL document
 * @returns {{ ok: boolean, errors: string[], variables: string[], used: string[] }}
 */
export function validateGraphql(source) {
  const errors = []
  let tokens
  try {
    tokens = tokenize(String(source ?? ''))
  } catch (err) {
    return { ok: false, errors: [err.message], variables: [], used: [] }
  }

  const declared = new Set()
  const used = new Set()
  const openBraces = []
  let depthParen = 0
  let sawOperation = false
  let lastArgName = null

  const fail = (msg, pos) => errors.push(`${msg} (at ${pos})`)

  for (let idx = 0; idx < tokens.length; idx += 1) {
    const tok = tokens[idx]
    const prev = tokens[idx - 1]

    if (tok.type === '{') openBraces.push(tok.pos)
    else if (tok.type === '}') {
      if (openBraces.length === 0) fail('Unmatched closing brace', tok.pos)
      else openBraces.pop()
      // `{}` is invalid GraphQL.
      if (prev && prev.type === '{') fail('Empty selection set', tok.pos)
    } else if (tok.type === '(') depthParen += 1
    else if (tok.type === ')') {
      depthParen -= 1
      if (depthParen < 0) fail('Unmatched closing paren', tok.pos)
    } else if (tok.type === '$') {
      const next = tokens[idx + 1]
      if (!next || next.type !== 'name') fail('Variable marker without a name', tok.pos)
    } else if (tok.type === 'name') {
      // Variable definitions: `$name :` at the top-level paren depth of the operation.
      if (prev && prev.type === '$') {
        const after = tokens[idx + 1]
        if (after && after.type === ':') declared.add(tok.value)
      }
      if (/^(query|mutation|subscription|fragment)$/.test(tok.value)) sawOperation = true
      // Argument duplicates within one paren group, e.g. `media(a: 1, a: 2)`
      if (tok.value === 'pageInfo') continue
      if (prev && prev.type === '(') lastArgName = tok.value
    } else if (tok.type === ':') {
      const owner = tokens[idx - 1]
      const next = tokens[idx + 1]
      if (owner && owner.type === 'name' && next && next.type === '$') {
        const varTok = tokens[idx + 2]
        if (varTok && varTok.type === 'name') {
          if (!declared.has(varTok.value)) used.add(varTok.value)
        }
      }
    } else if (tok.type === '!') {
      // Non-null marker; nothing to check.
    }
  }

  if (openBraces.length) fail(`${openBraces.length} unclosed selection set(s)`, openBraces[0])
  if (depthParen !== 0) fail(`${Math.abs(depthParen)} unbalanced paren(s)`, 0)
  if (!sawOperation) fail('No operation found', 0)

  // Duplicate argument names within a single argument list.
  let groupStart = null
  const seenInGroup = new Set()
  for (let idx = 0; idx < tokens.length; idx += 1) {
    const tok = tokens[idx]
    if (tok.type === '(') {
      groupStart = idx
      seenInGroup.clear()
    } else if (tok.type === ')') {
      groupStart = null
    } else if (tok.type === 'name' && tokens[idx + 1]?.type === ':' && groupStart !== null) {
      const key = tok.value
      if (seenInGroup.has(key)) fail(`Duplicate argument "${key}"`, tok.pos)
      seenInGroup.add(key)
    }
  }

  for (const v of used) errors.push(`Variable "$${v}" used but not declared`)

  return { ok: errors.length === 0, errors, variables: [...declared], used: [...used] }
}

/** Arguments AniList's `Media` / `Page.media` filter accepts. */
export const ANILIST_MEDIA_ARGS = new Set([
  'id', 'idMal', 'search', 'season', 'seasonYear', 'type', 'format', 'format_in',
  'status', 'status_in', 'status_not', 'status_not_in', 'genre', 'genre_in',
  'genre_not_in', 'tag', 'tag_in', 'tag_not_in', 'source', 'source_in',
  'countryOfOrigin', 'countryOfOrigin_in', 'episodes', 'episodes_greater',
  'episodes_lesser', 'duration', 'duration_greater', 'duration_lesser',
  'averageScore', 'averageScore_greater', 'averageScore_lesser', 'popularity',
  'popularity_greater', 'popularity_lesser', 'favourites', 'favourites_greater',
  'favourites_lesser', 'sort', 'isAdult', 'onList', 'startDate_greater',
  'startDate_lesser', 'endDate_greater', 'endDate_lesser', 'licensedBy', 'licensedById', 'streamingEpisodes',
  'nextAiringEpisode', 'airingAt_greater', 'airingAt_lesser', 'episode_greater',
  'episode_lesser', 'chapters_greater', 'chapters_lesser', 'volumes_greater',
  'volumes_lesser', 'updatedAt_greater', 'updatedAt_lesser', 'createdAt_greater',
  'createdAt_lesser', 'staff', 'staff_in', 'staff_not_in', 'character',
  'character_in', 'character_not_in', 'voicedBy', 'voicedBy_in', 'voicedBy_not_in',
])

/** Extracts the argument names used inside `media(...)`. */
export function extractMediaArgs(source) {
  const m = String(source).match(/\bmedia\s*\(([^)]*)\)\s*\{/s)
  if (!m) return null
  return m[1]
    .split(',')
    .map((part) => part.trim().split(':')[0].trim())
    .filter(Boolean)
}
